function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  iamRevokeUrl: 'https://httpbin.org/post',
  iamVerifyUrl: 'https://httpbin.org/post',
  saasRevokeUrl: 'https://httpbin.org/post',
  saasVerifyUrl: 'https://httpbin.org/post',
  itHrUrl: 'https://httpbin.org/post',
  timeoutMs: 20000,
  saasApps: ['slack', 'google_workspace', 'github', 'notion', 'jira'],
  allowSimulation: true
};

const hook = ref('Webhook - Offboarding Request');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const employeeId = String(body.employeeId || body.employee_id || '').trim();
const email = String(body.email || body.workEmail || '').trim().toLowerCase();
const userId = String(body.userId || body.user_id || body.iamId || '').trim();
const lastDay = String(body.lastDay || body.last_day || body.terminationDate || '').trim();
const reason = String(body.reason || 'resignation').trim();
const requestedBy = String(body.requestedBy || body.requested_by || 'system').trim();

if (!employeeId) errors.push('employeeId is required');
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('valid email is required');
if (!lastDay) errors.push('lastDay / terminationDate is required');

const valid = errors.length === 0;
const effectiveUserId = userId || ('user-' + employeeId);

let iamRevokeUrl = CONFIG.iamRevokeUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  iamRevokeUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    employee: {
      employeeId,
      email,
      userId: effectiveUserId,
      lastDay,
      reason,
      requestedBy
    },
    urls: {
      iamRevoke: iamRevokeUrl,
      iamVerify: CONFIG.iamVerifyUrl,
      saasRevoke: CONFIG.saasRevokeUrl,
      saasVerify: CONFIG.saasVerifyUrl,
      itHr: CONFIG.itHrUrl
    },
    requestId: body.requestId || ('offboard-' + Date.now())
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Validate & Prepare');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const ok = status >= 200 && status < 300;

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    employee: ctx.employee,
    urls: ctx.urls,
    results: {
      iamRevoke: { ok, status }
    }
  }
}];

