function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process SaaS Verify');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const itHrOk = status >= 200 && status < 300;

const results = {
  ...ctx.results,
  itHr: { ok: itHrOk, status }
};

const checks = [
  results.iamRevoke?.ok,
  results.iamVerify?.verified,
  results.saasRevoke?.ok,
  results.saasVerify?.verified,
  results.itHr?.ok
];
const passed = checks.filter(Boolean).length;
const total = checks.length;
const allPassed = passed === total;

return [{
  json: {
    requestId: ctx.requestId,
    employee: ctx.employee,
    results,
    compliance: {
      status: allPassed ? 'fully_revoked' : (passed > 0 ? 'partial' : 'failed'),
      checksPassed: passed,
      checksTotal: total,
      iamVerified: !!results.iamVerify?.verified,
      saasVerified: !!results.saasVerify?.verified,
      completedAt: new Date().toISOString()
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Build Final Report');

const httpStatus = ctx.compliance.status === 'fully_revoked' ? 200 : (ctx.compliance.status === 'partial' ? 207 : 502);

const body = {
  status: ctx.compliance.status,
  requestId: ctx.requestId,
  employee: {
    employeeId: ctx.employee.employeeId,
    email: ctx.employee.email,
    userId: ctx.employee.userId,
    lastDay: ctx.employee.lastDay,
    reason: ctx.employee.reason
  },
  revocation: ctx.results,
  compliance: ctx.compliance
};

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.requestId
  }
}];
